'use strict';
const paths={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',tree:'M12 3v5 M5 16v-5h14v5 M12 8v8 M2 16h6v5H2z M9 16h6v5H9z M16 16h6v5h-6z M9 2h6v5H9z',home:'m3 10 9-7 9 7 M5 9v12h14V9 M9 21v-7h6v7',car:'m5 7 2-4h10l2 4 M3 8h18v10H3z M5 18v3 M19 18v3 M6 12h2 M16 12h2',chart:'M4 3v18h18 M8 16v-5 M13 16V7 M18 16V4',settings:'M4 7h16 M4 17h16 M8 4v6 M16 14v6',down:'m6 9 6 6 6-6',right:'m9 5 7 7-7 7',arrow:'M5 12h14 m-5-5 5 5-5 5',plus:'M12 4v16 M4 12h16',search:'M10 3a7 7 0 1 0 0 14 7 7 0 0 0 0-14 M15 15l6 6',battery:'M2 6h18v12H2z M22 10v4 M6 9v6 M10 9v6 M14 9v6',sun:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M12 2v2 M12 20v2 M2 12h2 M20 12h2 M5 5l1 1 M18 18l1 1 M5 19l1-1 M18 6l1-1',bolt:'m13 2-9 12h7l-1 8 10-13h-8z',cpu:'M6 6h12v12H6z M9 9h6v6H9z M9 2v4 M15 2v4 M9 18v4 M15 18v4 M2 9h4 M2 15h4 M18 9h4 M18 15h4',x:'m6 6 12 12 M6 18 18 6',check:'m5 12 4 4L19 6',alert:'m12 3 10 18H2z M12 9v5 M12 17v1',upload:'M12 16V3 m-5 5 5-5 5 5 M4 15v6h16v-6',clock:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18 M12 7v5l4 2',users:'M9 3a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M2 21v-3a7 7 0 0 1 14 0v3 M17 4a4 4 0 0 1 0 7 M19 14a5 5 0 0 1 3 5v2',file:'M5 2h9l5 5v15H5z M14 2v6h5 M8 12h8 M8 16h8',edit:'m4 16 12-12 4 4L8 20H4z M14 6l4 4'};
const icon=(n)=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.grid}"/></svg>`;
const esc=(s)=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
Object.assign(paths,{user:'M12 3a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M4 22v-3a8 8 0 0 1 16 0v3',logout:'M9 3H3v18h6 M13 7l5 5-5 5 M8 12h10',download:'M12 3v12 m-5-5 5 5 5-5 M4 17v4h16v-4',gear:'M9 3h6l1 3 3 1 2 5-2 5-3 1-1 3H9l-1-3-3-1-2-5 2-5 3-1z M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8',shield:'m12 2 9 4v6c0 5-9 10-9 10S3 17 3 12V6z M8 12l3 3 5-6',building:'M5 22V3h14v19 M2 22h20 M8 6h2 M14 6h2 M8 10h2 M14 10h2 M8 14h2 M14 14h2 M10 22v-4h4v4',pause:'M8 4v16 M16 4v16',play:'m7 3 14 9-14 9z',back:'M20 12H4 m6-6-6 6 6 6',network:'M12 2 3 21h18z M8 9h8 M6 15h12 M12 2v19',list:'M8 5h13 M8 12h13 M8 19h13 M3 5h1 M3 12h1 M3 19h1'});
const seeds=[
 {name:'House R01',type:'Residential',subtype:'Detached house',icon:'home',power:2.4,pv:4.8,ready:true,fresh:true,algorithm:'RBC · Self-consumption'},
 {name:'House R02',type:'Residential',subtype:'Detached house',icon:'home',power:3.1,pv:3.6,ready:false,fresh:true,algorithm:'RBC · Self-consumption'},
 {name:'Apartment R03',type:'Residential',subtype:'Apartment',icon:'building',power:null,pv:null,ready:true,fresh:false,algorithm:'Not confirmed'},
 {name:'House R04',type:'Residential',subtype:'Detached house',icon:'home',power:1.8,pv:2.1,ready:true,fresh:true,algorithm:'RBC · Self-consumption'},
 {name:'Office R05',type:'Commercial',subtype:'Office',icon:'building',power:4.2,pv:5.2,ready:true,fresh:true,algorithm:'MPC · Cost'},
 {name:'House R06',type:'Residential',subtype:'Semi-detached house',icon:'home',power:2.6,pv:2.9,ready:true,fresh:true,algorithm:'RBC · Self-consumption'}
];
const communities=[{name:'Living Lab',place:'Porto',manager:'Living Lab management',cadence:15,salePercent:80,priceSource:'Community reference price',sites:makeSites('lab',6)},{name:'São Mamede',place:'Matosinhos',manager:'São Mamede management',cadence:60,salePercent:80,priceSource:'Community reference price',sites:makeSites('sm',3)}];
function makeSites(prefix,n){return seeds.slice(0,n).map((s,i)=>({...s,id:`${prefix}-${i+1}`,name:prefix==='sm'?s.name.replace('R0','S0'):s.name,importLimit:6.9,exportLimit:3.6,capacity:10,assets:[
 {id:'meter',name:'Grid meter',kind:'Grid meter',icon:'bolt',limit:'Bidirectional measurement',value:-2.4,quantity:'Net grid power',tag:`demo.${prefix}.${i+1}.grid.power`,unit:'kW',interval:15},
 {id:'pv',name:'Solar PV',kind:'PV system',icon:'sun',limit:'Generation 0–5 kW',value:s.pv,quantity:'Solar generation',tag:`demo.${prefix}.${i+1}.pv.power`,unit:'kW',interval:15},
 {id:'battery',name:'Battery',kind:'Battery',icon:'battery',limit:'Charge / discharge 0–3 kW',value:64,quantity:'State of charge',tag:`demo.${prefix}.${i+1}.battery.soc`,unit:'%',interval:30},
 {id:'charger',name:'EV charger',kind:'EV charger',icon:'car',limit:'Charging 0–7.4 kW',value:!s.ready?null:2.3,quantity:'Charging power',tag:!s.ready?'':`demo.${prefix}.${i+1}.evse.power`,unit:'kW',interval:15}
 ]}));}
let state={community:0,page:'overview',site:null,tab:'summary',dropdown:false,search:'',filter:'all',inventory:'sites',view:'list',range:'24h',live:true,metric:'energy',pending:{},drawer:null,asset:null,assetTab:'overview'};
const app=document.getElementById('app'),overlay=document.getElementById('overlay');
const comm=()=>communities[state.community];
const scoped=()=>comm().sites;
const chosen=()=>scoped().find(s=>s.id===state.site)||scoped()[0];
let currentAssets=()=>chosen()?.assets||[];
const num=(v,d=1)=>v==null?'—':Number(v).toLocaleString('en-GB',{minimumFractionDigits:d,maximumFractionDigits:d});
const time=t=>new Date(t).toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit',second:'2-digit'});
const shortTime=t=>new Date(t).toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit'});
const status=(text,tone='')=>`<span class="status ${tone}"><i class="dot"></i>${text}</span>`;
const button=(text,action,ic='',primary=false)=>`<button type="button" class="btn ${primary?'primary':''}" data-action="${action}">${ic?icon(ic):''}${text}</button>`;
const title=(heading,sub,actions='')=>`<header class="pagehead"><div><div class="eyebrow">${esc(comm().name)}</div><h1>${heading}</h1><p class="subtitle">${sub}</p></div><div class="actions">${actions}</div></header>`;
let previousFocus=null,chartCounter=0;
const seriesCache=new Map();
const metricNames={solar:'Solar generation',energy:'Consumption & solar production',grid:'Grid import & export',storage:'Battery state of charge',charging:'EV charging power'};
const hours=()=>state.range==='1h'?1:state.range==='7d'?168:24;
function scopeId(){return state.page==='sites'&&state.site?state.site+(state.equipment?'-'+state.equipment:''):`community-${state.community}`;}
function sample(t,scope,metric){const seed=[...scope].reduce((a,c)=>a+c.charCodeAt(0),0);const scale=scope.startsWith('community')?comm().sites.length:1;const phase=(t%86400000)/86400000*Math.PI*2;const jitter=Math.sin(t/13000+seed)*.11;let a=scale*(1.9+.6*Math.sin(phase-1)+.25*Math.sin(phase*4)+jitter),b=scale*Math.max(0,4*Math.sin(phase-Math.PI/2));if(metric==='solar'){a=b;b=null;}if(metric==='grid'){a=Math.max(a-b,0);b=Math.max(b-(scale*1.9),0);}if(metric==='storage'){a=64+18*Math.sin(phase-1)+jitter*4;b=null;}if(metric==='charging'){a=scale*(1.3+1.1*Math.sin(phase*.8)**2+jitter);b=null;}return {t,a:Math.max(0,a),b};}
function series(){const key=`${scopeId()}|${state.metric}|${state.range}`;if(!seriesCache.has(key)){const end=Date.now(),duration=hours()*3600000;seriesCache.set(key,Array.from({length:145},(_,i)=>sample(end-duration+i*duration/144,scopeId(),state.metric)));}return seriesCache.get(key);}
function plot(data){const w=1000,h=280,left=42,right=975,top=18,bottom=240;const max=state.metric==='storage'?100:Math.max(4,...data.flatMap(p=>[p.a,p.b||0]))*1.15;const minT=data.at(-1).t-hours()*3600000,maxT=data.at(-1).t;const x=t=>left+(t-minT)/(maxT-minT)*(right-left);const y=v=>bottom-v/max*(bottom-top);const line=k=>data.map((p,i)=>`${i?'L':'M'}${x(p.t).toFixed(2)} ${y(p[k]).toFixed(2)}`).join(' ');const one=line('a');return `<svg class="plot" viewBox="0 0 ${w} ${h}" role="img" aria-label="Simulated ${metricNames[state.metric]}, ${state.range}">${[0,1,2,3].map(i=>{let v=max*i/3;return `<line class="grid" x1="${left}" x2="${right}" y1="${y(v)}" y2="${y(v)}"/><text x="4" y="${y(v)+4}">${num(v,0)}</text>`;}).join('')}<text x="4" y="10">${state.metric==='storage'?'%':'kW'}</text><path d="${one} L${right} ${bottom} L${left} ${bottom}Z" fill="#18a56f" opacity=".06"/><path class="curve" d="${one}"/>${data[0].b!=null?`<path class="curve2" d="${line('b')}"/>`:''}<circle cx="${right}" cy="${y(data.at(-1).a)}" r="3" fill="var(--brand)"/>${[0,1,2,3,4].map(i=>{const t=minT+(maxT-minT)*i/4;return `<text x="${left+i*(right-left)/4}" y="267" text-anchor="${i===4?'end':i===0?'start':'middle'}">${hours()>24?new Date(t).toLocaleDateString('en-GB',{day:'2-digit',month:'short'}):shortTime(t)}</text>`;}).join('')}</svg>`;}
function rangeButtons(){return `<div class="chartcontrols"><div class="pilltabs" aria-label="Time range">${[['1h','1 hour'],['24h','24 hours'],['7d','7 days']].map(([v,l])=>`<button type="button" data-range="${v}" class="${state.range===v?'active':''}" aria-pressed="${state.range===v}">${l}</button>`).join('')}</div><button class="btn livebtn ${state.live?'on':''}" data-action="live" aria-pressed="${state.live}">${icon(state.live?'pause':'play')}${state.live?'Pause live':'Go live'}</button></div>`;}
function chart(){const data=series();const names=state.metric==='energy'?['Consumption','Solar production']:state.metric==='grid'?['Import','Export']:state.metric==='storage'?['State of charge']:state.metric==='solar'?['Solar generation']:['Charging power'];const last=data.at(-1);return `<section class="surface chart-section"><div class="sectionhead"><h2>${metricNames[state.metric]}</h2>${rangeButtons()}</div><div class="chartmeta"><div class="legend">${names.map((n,i)=>`<span class="${i?'second':''}">${n}</span>`).join('')}</div><div class="chartlast"><strong data-chart-value>${num(last.a)} ${state.metric==='storage'?'%':'kW'}</strong><small>latest simulated value</small></div></div><div data-chart-plot>${plot(data)}</div><div class="chartfooter"><span class="status ${state.live?'':'unknown'}"><i class="dot"></i>${state.live?'Live demo · rolling history':'History paused'}</span><small>Updated <span data-chart-time>${time(last.t)}</span> · <span data-chart-count>${data.length}</span> samples · simulated</small></div></section>`;}
function dataExplorer(){return `<div class="toolbar"><div><h2>Community series</h2><p class="subtitle">Explore raw measurements over time. Switch to KPIs for calculated indicators.</p></div><label class="metric-select">Series<select id="metric-select">${Object.entries(metricNames).map(([v,l])=>`<option value="${v}" ${state.metric===v?'selected':''}>${l}</option>`).join('')}</select></label></div>${chart()}<p class="footnote">The live window loads history first, then appends incoming samples. A paused view stays fixed until you resume live.</p>`;}
function siteRows(list){return list.map(s=>`<tr><td><button class="namebtn" data-site="${s.id}"><span class="square">${icon(s.icon)}</span><span>${esc(s.name)}<small>${s.type} · ${s.subtype}</small></span></button></td><td>${status(s.ready?'Complete':'1 warning',s.ready?'':'warn')}</td><td>${status(s.fresh?'Recent demo data':'No data for 2 h',s.fresh?'':'unknown')}</td><td>${num(s.power)}${s.power==null?'':' kW'}</td><td><span class="badge">${s.algorithm}</span></td><td><button aria-label="Open ${esc(s.name)}" data-site="${s.id}">${icon('right')}</button></td></tr>`).join('');}
function siteTable(list){return `<div class="tablewrap"><table><thead><tr><th>Site</th><th>Configuration</th><th>Latest data</th><th>Consumption</th><th>Control</th><th></th></tr></thead><tbody>${siteRows(list)||'<tr><td colspan="6" class="empty">No sites match your search.</td></tr>'}</tbody></table></div>`;}
function overview(){const list=scoped(),live=list.filter(s=>s.fresh),warn=list.filter(s=>!s.ready||!s.fresh);const power=live.reduce((a,s)=>a+s.power,0),pv=live.reduce((a,s)=>a+s.pv,0);state.metric='energy';return title('Overview','Your community at a glance.',button('Community settings','community-settings','gear'))+`<div class="metrics"><div class="metric"><label>Sites reporting</label><strong>${live.length} <span>/ ${list.length} sites</span></strong><small>${list.length-live.length} without recent data</small></div><div class="metric"><label>Consumption snapshot</label><strong>${num(power)} <span>kW</span></strong><small>Example snapshot · ${live.length}/${list.length} sites</small></div><div class="metric"><label>Solar production snapshot</label><strong>${num(pv)} <span>kW</span></strong><small>Example snapshot · ${live.length}/${list.length} sites</small></div><div class="metric"><label>EVs charging</label><strong>${Math.min(2,list.length)} <span>/ ${Math.min(3,list.length)} registered</span></strong><small>Example · next departure at 18:00</small></div></div><div class="overviewstack">${chart()}<section class="surface attention-strip"><div class="sectionhead"><h2>Needs attention</h2><span class="badge">${warn.length}</span></div>${warn.map(s=>`<button class="issue" data-site="${s.id}"><strong><i class="dot warn"></i>${esc(s.name)}</strong><small>${!s.fresh?'No data for 2 hours. Current control status cannot be confirmed.':'EV charger power tag is missing. Complete sensor configuration.'}</small></button>`).join('')||'<p class="muted">No configuration warnings.</p>'}<button class="btn text" data-page="sites">View all sites ${icon('arrow')}</button></section></div><section class="tablewrap"><div class="sectionhead"><h2>Community sites</h2><button class="btn text" data-page="sites">Manage sites ${icon('arrow')}</button></div>${siteTable(list)}</section><p class="footnote">Preview values only. Configuration completeness and measurement availability are separate states.</p>`;}
function inventoryTabs(){return `<div class="inventory-toolbar"><div class="pilltabs" aria-label="Inventory category">${[['sites','Sites'],['vehicles','Electric vehicles']].map(([v,l])=>`<button data-inventory="${v}" class="${state.inventory===v?'active':''}" aria-pressed="${state.inventory===v}">${l}</button>`).join('')}</div>${state.inventory==='sites'?`<div class="pilltabs" aria-label="Site view"><button data-view="list" class="${state.view==='list'?'active':''}" aria-pressed="${state.view==='list'}">${icon('list')} List</button><button data-view="topology" class="${state.view==='topology'?'active':''}" aria-pressed="${state.view==='topology'}">${icon('tree')} Topology</button></div>`:''}</div>`;}
function filteredSites(){return siteTable(scoped().filter(s=>s.name.toLowerCase().includes(state.search.toLowerCase())&&(state.filter==='all'||state.filter==='warnings'&&(!s.ready||!s.fresh)||state.filter==='complete'&&s.ready)));}
function siteList(){return title('Inventory','Your community inventory, its connections and current state.',button('Import Excel','import','upload')+button('Add site','add-site','plus',true))+inventoryTabs()+(state.inventory==='vehicles'?vehicles():state.view==='topology'?communityTopology():`<div class="toolbar"><label class="search">${icon('search')}<input id="site-search" aria-label="Search sites" placeholder="Search sites…" value="${esc(state.search)}"></label><select id="site-filter" aria-label="Filter sites"><option value="all" ${state.filter==='all'?'selected':''}>All states</option><option value="warnings" ${state.filter==='warnings'?'selected':''}>Needs attention</option><option value="complete" ${state.filter==='complete'?'selected':''}>Configuration complete</option></select></div><div id="site-results">${filteredSites()}</div><p class="footnote">Open a site to explore its overview, topology, equipment, data and algorithm.</p>`);}
function tree(){return `<aside class="tree" aria-label="Site navigator"><div class="eyebrow">Site navigator</div><button data-action="all-sites">${icon('tree')}${esc(comm().name)}<span class="treecount">${scoped().length}</span></button>${scoped().map(s=>`<button data-site="${s.id}" class="${state.site===s.id?'selected':''}" ${state.site===s.id?'aria-current="true"':''}>${icon(s.icon)}${esc(s.name)}<i class="dot ${s.ready&&s.fresh?'':'warn'}"></i></button>${state.site===s.id?s.assets.map(a=>`<button class="child ${state.equipment===a.id?'selected':''}" data-asset="${a.id}">${icon(a.icon)}${a.name}</button>`).join(''):''}`).join('')}</aside>`;}
function graphNode(x,y,w,label,sub,ic,action,root=false){return `<g class="node ${root?'root':''}" role="button" tabindex="0" aria-label="${esc(label)}" data-${action[0]}="${esc(action[1])}" transform="translate(${x} ${y})"><rect width="${w}" height="76" rx="9"/><g transform="translate(13 13)" fill="none" stroke="${root?'#12845a':'#61706a'}" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><path d="${paths[ic]}"/></g><text class="title" x="44" y="30">${esc(label)}</text><text x="14" y="57">${esc(sub)}</text></g>`;}
function edgeLabel(x,y,w,lines){return `<g class="edge-tag" transform="translate(${x} ${y})"><rect width="${w}" height="${lines.length*16+12}" rx="5"/>${lines.map((l,i)=>`<text x="${w/2}" y="${18+i*16}" text-anchor="middle">${l}</text>`).join('')}</g>`;}
function arrowDefs(){return `<defs><marker id="arrow-end" viewBox="0 0 8 8" refX="7" refY="4" markerWidth="6" markerHeight="6" orient="auto-start-reverse"><path d="M1 1L7 4L1 7" fill="none" stroke="#7da18f" stroke-width="1.4"/></marker></defs>`;}
function assetTable(){return `<div class="sectionhead"><h2>Equipment</h2>${button('Add equipment','add-asset','plus')}</div><div class="tablewrap"><table><thead><tr><th>Equipment</th><th>Latest reading</th><th>Data availability</th><th></th></tr></thead><tbody>${currentAssets().map(a=>`<tr><td><button class="namebtn" data-asset="${a.id}"><span class="square">${icon(a.icon)}</span><span>${a.name}<small>${a.kind}</small></span></button></td><td>${a.value==null?'—':num(a.value)+' '+a.unit}</td><td>${status(!chosen().fresh?'Stale':a.value==null?(a.tag?'Waiting for data':'Missing power tag'):'Available',!chosen().fresh?'unknown':a.value==null?'warn':'')}</td><td><button aria-label="Inspect ${a.name}" data-asset="${a.id}">${icon('right')}</button></td></tr>`).join('')}</tbody></table></div><p class="footnote">Select equipment to inspect its readings, missing data and sensor configuration.</p>`;}
function algorithm(){const s=chosen();return `<section class="surface"><div class="sectionhead"><div><div class="eyebrow">Site execution</div><h2>${s.algorithm}</h2></div>${status(s.fresh?'Running · example':'Unknown state',s.fresh?'':'unknown')}</div><div class="kv"><div><small>Model / version</small><strong>${s.fresh?(s.algorithm.startsWith('MPC')?'MPC · v1.1':'RBC · v1.2'):'Not confirmed'}</strong></div><div><small>Last confirmation</small><strong>${s.fresh?'11 Oct · 11:45:00':'No recent confirmation'}</strong></div><div><small>Scope</small><strong>${esc(s.name)} · eligible equipment</strong></div><div><small>Fallback behaviour</small><strong>To be defined with the control service</strong></div></div>${state.pending[s.id]?`<div class="notice neutral" style="margin-top:20px"><span>${icon('clock')}</span><div><strong>Simulated request: ${esc(state.pending[s.id])}</strong>Awaiting execution acknowledgement. The active algorithm has not changed.</div></div>`:''}<div class="actions" style="margin-top:24px">${button('Change algorithm','algorithm','cpu',true)}${button('View activity','activity','file')}</div></section><p class="footnote">A model change is a request. “Running” changes only after the execution service confirms it.</p>`;}
function siteSettings(){const s=chosen();return `<section class="surface"><div class="sectionhead"><h2>Site details</h2>${button('Edit site','edit-site','edit')}</div><div class="kv"><div><small>Name</small><strong>${esc(s.name)}</strong></div><div><small>Type / subtype</small><strong>${s.type} · ${s.subtype}</strong></div><div><small>Address</small><strong>12 Example Street · ${esc(comm().place)}</strong></div><div><small>CPE</small><strong>Not provided · optional</strong></div><div><small>Contracted power</small><strong>6.9 kVA</strong></div><div><small>Operational limits</small><strong>Import ≤ ${num(s.importLimit)} kW · Export ≤ ${num(s.exportLimit)} kW</strong></div></div><div class="settingsrow"><div><h3>Energy contracts</h3><p>Common community rules, site-specific terms and an external comparison contract.</p></div>${button('View terms','contracts','file')}</div></section>`;}
function siteDetailOriginal(){const s=chosen();return `<div class="workspace">${tree()}<div class="detail"><div class="eyebrow">Sites / ${esc(s.name)}</div><div class="sitehead"><div><h1>${esc(s.name)}</h1><p class="subtitle">${s.type} · ${s.subtype} · ${esc(comm().place)}</p></div>${button('Edit site','edit-site','edit')}</div><nav class="tabs" aria-label="Site sections">${[['summary','Overview'],['topology','Topology'],['assets','Equipment'],['algorithm','Algorithm'],['settings','Settings']].map(([v,l])=>`<button data-tab="${v}" class="${state.tab===v?'active':''}" aria-current="${state.tab===v?'page':'false'}">${l}</button>`).join('')}</nav><div class="content">${!s.fresh?`<div class="notice"><span>${icon('alert')}</span><div><strong>No recent data</strong>Last observation 2 hours ago. Current equipment and control states are unknown.</div></div>`:!s.ready?`<div class="notice"><span>${icon('alert')}</span><div><strong>Power sensor not configured</strong>The EV charger is missing its external tag. <button class="btn text" data-asset="charger">Inspect equipment</button></div></div>`:''}${state.tab==='topology'?siteTopology():state.tab==='assets'?assetTable():state.tab==='algorithm'?algorithm():state.tab==='settings'?siteSettings():state.tab==='data'?`<div class="toolbar"><h2>Site measurements</h2><label class="metric-select">Series<select id="metric-select">${Object.entries(metricNames).map(([v,l])=>`<option value="${v}" ${state.metric===v?'selected':''}>${l}</option>`).join('')}</select></label></div>${s.fresh?chart():'<section class="surface empty">No recent measurements. Live updates resume when the source reconnects.</section>'}`:`<div class="summaryrow"><div><small>Configuration</small><strong>${s.ready?'Complete':'1 warning'}</strong></div><div><small>Equipment</small><strong>${s.assets.length}</strong></div><div><small>Consumption snapshot</small><strong>${num(s.power)} ${s.power==null?'':'kW'}</strong></div><div><small>Data availability</small><strong>${s.fresh?'Recent':'Stale · 2 h'}</strong></div></div>${s.fresh?chart():'<section class="surface empty">No recent readings to display.</section>'}<section class="surface" style="margin-top:20px"><div class="sectionhead"><h2>Equipment at a glance</h2><button class="btn text" data-tab="assets">All equipment ${icon('arrow')}</button></div><div class="equipment-strip">${s.assets.map(a=>`<button data-asset="${a.id}">${icon(a.icon)}<span><strong>${a.name}</strong><small>${a.value==null?'No reading':num(a.value)+' '+a.unit}${!s.fresh?' · stale':''}</small></span>${icon('right')}</button>`).join('')}</div></section><section class="surface" style="margin-top:20px"><div class="sectionhead"><h2>Site control</h2><button class="btn text" data-tab="algorithm">View algorithm ${icon('arrow')}</button></div><p>${s.algorithm}</p></section>`}</div></div></div>`;}
function vehicles(){return `<div class="sectionhead"><div><h2>Electric vehicles</h2><p class="subtitle">Community vehicles, their current connection and flexibility sessions.</p></div></div><div class="notice neutral"><span>${icon('car')}</span><div><strong>Registered is not the same as connected</strong>Vehicle ownership comes from inventory. Connection and charging state come from observations.</div></div><div class="tablewrap"><table><thead><tr><th>Vehicle</th><th>Site / charger</th><th>Observed state</th><th>SoC</th><th>Departure / minimum</th><th></th></tr></thead><tbody>${scoped().slice(0,3).map((s,i)=>`<tr><td><button class="namebtn" data-vehicle="${i}"><span class="square">${icon('car')}</span>EV 0${i+1}</button></td><td><button class="btn text" data-site="${s.id}">${esc(s.name)}</button><small>EVSE 01</small></td><td>${status(s.fresh?'Charging':'Unknown',s.fresh?'':'unknown')}</td><td>${s.fresh?(i===0?'42%':'61%'):'—'}</td><td>${s.fresh?(i===0?'18:00 · ≥ 80%':'19:30 · ≥ 90%'):'No active session'}</td><td><button aria-label="Inspect EV 0${i+1}" data-vehicle="${i}">${icon('right')}</button></td></tr>`).join('')}</tbody></table></div>`;}
function insightsOriginal(){return title('Insights','Derived KPIs, trends and data coverage for this community.')+`<div class="notice neutral"><span>${icon('chart')}</span><div><strong>Illustrative KPI definitions</strong>Calculations and service integration will be validated before displaying real results. Explore raw community charts in Measurements.</div></div><div class="metrics"><div class="metric"><label>Self-consumption</label><strong>68 <span>%</span></strong><small>Example · solar energy consumed locally</small></div><div class="metric"><label>Self-sufficiency</label><strong>42 <span>%</span></strong><small>Example · demand supplied locally</small></div><div class="metric"><label>Peak import</label><strong>19.8 <span>kW</span></strong><small>Example · observed maximum</small></div><div class="metric"><label>Data coverage</label><strong>92 <span>%</span></strong><small>Example · received / expected intervals</small></div></div><section class="surface"><div class="sectionhead"><h2>Weekly self-consumption</h2><span class="badge">Illustrative data</span></div><div class="insightbars">${[40,56,45,70,61,80,68].map((v,i)=>`<div style="height:${v}%"><small>${['Mon','Tue','Wed','Thu','Fri','Sat','Sun'][i]}</small></div>`).join('')}</div><div class="kv"><div><small>Scope</small><strong>${esc(comm().name)} · ${scoped().length} sites</strong></div><div><small>Missing observations</small><strong>1 site · 2 hours without readings</strong></div></div></section>`;}
function admin(){return title('Administration','Membership, energy rules, imports and operational records.')+`<section class="surface settings">${[['Community identity and operation',`${comm().name} · ${comm().place} · ${comm().cadence} s operation interval`,'community-settings','Edit community'],['Community energy contracts','Variable intra-community pricing. Member sales use 80% of that reference price, with site-specific conditions.','contracts','View contracts'],['Members and access','Community managers, end users and their site associations.','members','Manage members'],['Inventory import','Preview an Excel file, resolve row-level warnings, apply and verify.','import','Import Excel'],['Activity','Configuration changes and algorithm change requests.','activity','View activity']].map(([h,p,a,b])=>`<div class="settingsrow"><div><h3>${h}</h3><p>${esc(p)}</p></div>${button(b,a)}</div>`).join('')}</section>`;}
function toast(text){const t=document.getElementById('toast');t.textContent=text;t.style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.style.display='none',4500);}
function closeDrawer(){overlay.innerHTML='';app.inert=false;state.drawer=null;if(previousFocus?.isConnected)previousFocus.focus();}
function drawer(title,body,footer='',onSubmit=null){if(!overlay.innerHTML)previousFocus=document.activeElement;app.inert=true;overlay.innerHTML=`<div class="drawerback"><section class="drawer" role="dialog" aria-modal="true" aria-label="${title}"><div class="sectionhead"><div><div class="eyebrow">${esc(comm()?.name||'Community')} · Connected</div><h2>${title}</h2></div><button type="button" class="dismiss" data-action="close" aria-label="Close">${icon('x')}</button></div><form id="drawer-form">${body}${footer?`<div class="actions">${button('Cancel','close')}${footer}</div>`:''}</form></section></div>`;overlay.querySelector('form').addEventListener('submit',e=>{e.preventDefault();onSubmit?.(new FormData(e.target));});overlay.querySelector('button').focus();}
const save=(label='Save changes')=>`<button type="submit" class="btn primary">${label}</button>`;
const field=(label,name,value,type='text',extra='')=>`<label class="formlabel">${label}<input name="${name}" type="${type}" ${type==='number'?'step="any"':''} value="${esc(value)}" ${extra} required></label>`;
function inspectAsset(id){const a=currentAssets().find(x=>x.id===id),s=chosen();state.asset=id;state.drawer='asset';const form=`<div class="assetidentity"><span class="square">${icon(a.icon)}</span><div><strong>${esc(s.name)}</strong><small>${a.kind}</small></div></div>`+field('External tag','tag',a.tag)+field('Expected interval (seconds)','interval',a.interval,'number','min="1" step="1"')+`<p class="footnote">Saving a tag configures the sensor; it does not create observations or confirm live connectivity.</p>`;drawer(a.name+' settings',form,save(),data=>{const interval=Number(data.get('interval')),tag=String(data.get('tag')).trim();if(!Number.isInteger(interval)||interval<=0){toast('The interval must be a positive whole number.');return;}if(!tag){toast('Enter a tag.');return;}a.tag=tag;a.interval=interval;s.ready=s.assets.every(x=>x.tag);closeDrawer();render();toast('Sensor configuration saved in this prototype. Observations are unchanged.');});}
function action(a){
 if(a==='account'){state.userOpen=!state.userOpen;state.dropdown=false;render();return;}
 if(a==='logout'){state.loggedIn=false;state.userOpen=false;state.dropdown=false;state.site=null;state.equipment=null;render();return;}
 if(a==='profile'){state.userOpen=false;render();drawer('Profile','<div class="kv"><div><small>Name</small><strong>REC Manager</strong></div><div><small>Email</small><strong>rec@energaize.io</strong></div><div><small>Role</small><strong>Community manager</strong></div></div>');return;}
 if(a==='export-topology'){exportTopology();return;}
 if(a==='site-overview'){state.equipment=null;state.tab='summary';state.metric='energy';render();return;}
 if(a==='configure-equipment'){inspectAsset(state.equipment,'configuration');return;}

 if(a==='switch'){state.dropdown=!state.dropdown;render();return;}
 if(a==='close'){closeDrawer();return;}
 if(a==='all-communities'){state.userOpen=false;state.page='communities';state.dropdown=false;state.site=null;render();return;}
 if(a==='all-sites'){state.page='sites';state.site=null;state.equipment=null;state.inventory='sites';render();return;}
 if(a==='live'){state.live=!state.live;if(state.live){if(state.range==='7d')state.range='24h';seriesCache.delete(`${scopeId()}|${state.metric}|${state.range}`);}render();return;}
 if(a==='new-community'){state.dropdown=false;render();drawer('New community',field('Name','name','')+field('Location','place','')+`<label class="formlabel">Description<textarea name="description" rows="2" placeholder="Describe this community"></textarea></label><label class="formlabel">Managing entity · optional<input name="manager"></label><label class="formlabel">Operation interval<select name="cadence">${[[1,'1 second'],[5,'5 seconds'],[10,'10 seconds'],[15,'15 seconds'],[30,'30 seconds'],[60,'1 minute'],[300,'5 minutes'],[900,'15 minutes'],[1800,'30 minutes'],[3600,'1 hour']].map(([v,l])=>`<option value="${v}" ${v===15?'selected':''}>${l}</option>`).join('')}</select></label><div class="formcolumns"><label class="formlabel">Active from · optional<input type="date" name="from"></label><label class="formlabel">Active until · optional<input type="date" name="until"></label></div><p class="footnote">Start with an empty community. Add sites and equipment next; configure energy contracts in Administration.</p>`,save('Create community'),d=>{if(d.get('from')&&d.get('until')&&d.get('until')<d.get('from')){toast('The end date must follow the start date.');return;}communities.push({name:String(d.get('name')),place:String(d.get('place')),description:String(d.get('description')),manager:String(d.get('manager')||'Not assigned'),cadence:Number(d.get('cadence')),activeFrom:d.get('from'),activeUntil:d.get('until'),salePercent:80,priceSource:'Not configured',sites:[]});state.community=communities.length-1;state.site=null;state.equipment=null;state.page='sites';state.search='';state.filter='all';state.inventory='sites';state.view='list';closeDrawer();render();toast('Community created. Add your first site to get started.');});return;}

 if(a==='community-settings'){drawer('Community settings',field('Name','name',comm().name)+field('Managing entity','manager',comm().manager)+`<label class="formlabel">Operation interval<select name="cadence">${[[1,'1 second'],[5,'5 seconds'],[10,'10 seconds'],[15,'15 seconds'],[30,'30 seconds'],[60,'1 minute'],[300,'5 minutes'],[900,'15 minutes'],[1800,'30 minutes'],[3600,'1 hour']].map(([v,l])=>`<option value="${v}" ${v===comm().cadence?'selected':''}>${l}</option>`).join('')}</select></label><p class="footnote">Sensor sampling intervals are configured separately for each device.</p>`,save(),d=>{comm().name=String(d.get('name'));comm().manager=String(d.get('manager'));comm().cadence=Number(d.get('cadence'));closeDrawer();render();toast('Community settings saved in preview.');});return;}
 if(a==='edit-site'){const s=chosen();drawer('Edit site',field('Name','name',s.name)+field('Import limit (kW)','import',s.importLimit,'number','min="0"')+field('Export limit (kW)','export',s.exportLimit,'number','min="0"')+`<p class="footnote">Operational power limits in kW are separate from contracted apparent power in kVA.</p>`,save(),d=>{s.name=String(d.get('name'));s.importLimit=Number(d.get('import'));s.exportLimit=Number(d.get('export'));closeDrawer();render();toast('Site details saved in preview.');});return;}
 if(a==='algorithm'){drawer('Change algorithm',`<p class="subtitle">${esc(chosen().name)} · Select a compatible control model.</p><div class="notice neutral" style="margin-top:20px">Example options only. Actual compatibility must be checked with the execution service.</div><label class="formlabel">Algorithm<select name="algorithm"><option>RBC · Self-consumption</option><option>MPC · Cost</option></select></label><div class="kv"><div><small>Currently running</small><strong>${chosen().algorithm}</strong></div><div><small>After requesting</small><strong>Pending confirmation</strong></div></div>`,save('Simulate request'),d=>{state.pending[chosen().id]=String(d.get('algorithm'));closeDrawer();state.tab='algorithm';render();toast('Request simulated. No running algorithm was changed.');});return;}
 if(a==='contracts'){drawer('Energy contracts',`<div class="notice neutral">Shared community rules. Site-specific conditions and external comparison contracts will be configured separately.</div><div class="kv"><div><small>Intra-community purchase price</small><strong>Variable over time</strong></div><div><small>Member sale price</small><strong>${comm().salePercent}% of the intra-community reference</strong></div><div><small>Reference source</small><strong>${esc(comm().priceSource)}</strong></div><div><small>Grid purchase / sale</small><strong>Separate rules · not configured</strong></div></div><div class="actions" style="margin-top:22px">${button('Edit community terms','edit-contract','edit')}</div><p class="footnote">These are price rules, not billing calculations.</p>`);return;}
 if(a==='edit-contract'){drawer('Community price rules',field('Variable price reference','source',comm().priceSource)+field('Member sale (% of reference)','percentage',comm().salePercent,'number','min="0" max="100"')+`<p class="footnote">This preview covers the common variable price and member sale ratio. Full contract dates, components and site overrides remain part of implementation.</p>`,save(),d=>{comm().priceSource=String(d.get('source'));comm().salePercent=Number(d.get('percentage'));closeDrawer();render();toast('Example contract rules updated.');});return;}
 if(a==='import'){drawer('Import inventory',`<div class="steps"><span class="active">1. File</span>→<span>2. Review</span>→<span>3. Apply</span></div><p class="subtitle">Review the Excel contents before modifying inventory.</p><label class="formlabel">Excel file<input type="file" accept=".xlsx" disabled></label><div class="notice neutral"><span>${icon('file')}</span><div><strong>Backend integration to follow</strong>Preview → row errors and warnings → apply → verify sites, assets and sensors.</div></div><p class="footnote">File upload is disabled in this prototype.</p>`);return;}
 if(a==='members'){drawer('Members and access',`<div class="record">${icon('users')}<div><strong>Community manager</strong><small>Community inventory, sites and authorised control.</small></div></div><div class="record">${icon('home')}<div><strong>End user</strong><small>Assigned sites, equipment and flexibility sessions.</small></div></div><p class="footnote">Real user associations will come from the backend.</p>`);return;}
 if(a==='account-communities'){closeDrawer();action('all-communities');return;}
 if(a==='activity'){drawer('Activity · examples',`<div class="record">${icon('clock')}<div><strong>11:40 · Algorithm request</strong><small>MPC requested for a site. Awaiting execution acknowledgement.</small></div></div><div class="record">${icon('edit')}<div><strong>10:15 · Sensor configuration</strong><small>Sampling interval updated.</small></div></div><p class="footnote">Illustrative entries, not live audit records.</p>`);return;}
 if(a==='grid-info'){drawer('Grid connection',`<p class="subtitle">The site exchanges energy with the external grid. Import and export limits are shown on that connection.</p><div class="kv"><div><small>Import limit</small><strong>${num(chosen().importLimit)} kW</strong></div><div><small>Export limit</small><strong>${num(chosen().exportLimit)} kW</strong></div></div><p class="footnote">Limits constrain operation; live flow direction requires fresh power measurements.</p>`);return;}
 if(a==='add-site'||a==='add-asset'){drawer(a==='add-site'?'Add site':'Add equipment',`<p class="subtitle">The full form will use the backend catalogue and validation rules.</p><div class="kv"><div><small>Identity</small><strong>Name, type and subtype</strong></div><div><small>Location</small><strong>${a==='add-site'?'Address and coordinates':'Assigned site'}</strong></div><div><small>Technical details</small><strong>Ratings and operating limits</strong></div><div><small>After creation</small><strong>Configure sensors and review warnings</strong></div></div><p class="footnote">Creation is not connected in this prototype.</p>`);}
}
function vehicleDrawer(index){const s=scoped()[index],i=Number(index);drawer(`EV 0${i+1}`,`<div class="kv"><div><small>Site / charger</small><strong>${esc(s.name)} · EVSE 01</strong></div><div><small>Arrival</small><strong>${s.fresh?'11 Oct · 08:30':'No active session'}</strong></div><div><small>Departure</small><strong>${s.fresh?(i===0?'11 Oct · 18:00':'11 Oct · 19:30'):'No active session'}</strong></div><div><small>Minimum departure SoC</small><strong>${s.fresh?(i===0?'80%':'90%'):'Not requested'}</strong></div><div><small>Declared arrival SoC</small><strong>Optional · not supplied</strong></div><div><small>Observed SoC</small><strong>${s.fresh?(i===0?'42% · example':'61% · example'):'Unknown'}</strong></div></div><p class="footnote">Requested departure SoC and observed SoC are different values.</p>`);}
document.addEventListener('click',e=>{const t=e.target.closest('[data-action],[data-page],[data-site],[data-tab],[data-community],[data-asset],[data-range],[data-view],[data-inventory],[data-asset-tab],[data-vehicle],[data-device-tab],[data-insight-tab]');if(t){
 if(t.dataset.action){e.preventDefault();action(t.dataset.action);}
 else if(t.dataset.community!=null){state.community=Number(t.dataset.community);state.metric='energy';state.site=null;state.equipment=null;state.userOpen=false;state.dropdown=false;if(state.page==='communities')state.page='overview';render();}
 else if(t.dataset.page){state.page=t.dataset.page;state.site=null;state.equipment=null;state.userOpen=false;state.dropdown=false;if(state.page==='insights'||state.page==='overview')state.metric='energy';render();}
 else if(t.dataset.site){const wasDetail=state.page==='sites'&&!!state.site;state.page='sites';state.site=t.dataset.site;state.dropdown=false;if(!wasDetail)state.tab='summary';state.equipment=null;if(state.tab==='summary')state.metric='energy';render();}
 else if(t.dataset.tab){state.equipment=null;state.tab=t.dataset.tab;if(state.tab==='summary')state.metric='energy';render();}
 else if(t.dataset.asset){openEquipment(t.dataset.asset);}
 else if(t.dataset.assetTab){inspectAsset(state.asset,t.dataset.assetTab);}
 else if(t.dataset.range){state.range=t.dataset.range;state.live=false;render();}
 else if(t.dataset.view){state.view=t.dataset.view;render();}
 else if(t.dataset.inventory){state.inventory=t.dataset.inventory;render();}
 else if(t.dataset.vehicle!=null){vehicleDrawer(t.dataset.vehicle);}
 else if(t.dataset.deviceTab){state.deviceTab=t.dataset.deviceTab;render();}
 else if(t.dataset.insightTab){state.insightTab=t.dataset.insightTab;render();}
 }else if(e.target.classList.contains('drawerback'))closeDrawer();else if((state.dropdown&&!e.target.closest('.switchwrap'))||(state.userOpen&&!e.target.closest('.topbar-right'))){state.dropdown=false;state.userOpen=false;render();}});
document.addEventListener('input',e=>{if(e.target.id==='site-search'){state.search=e.target.value;document.getElementById('site-results').innerHTML=filteredSites();}});
document.addEventListener('change',e=>{if(e.target.id==='site-filter'){state.filter=e.target.value;document.getElementById('site-results').innerHTML=filteredSites();}if(e.target.id==='metric-select'){state.metric=e.target.value;render();}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(overlay.innerHTML)closeDrawer();else if(state.dropdown||state.userOpen){state.dropdown=false;state.userOpen=false;render();}}if((e.key==='Enter'||e.key===' ')&&e.target.matches('g[role="button"]')){e.preventDefault();e.target.dispatchEvent(new MouseEvent('click',{bubbles:true}));}if(e.key==='Tab'&&overlay.innerHTML){const nodes=[...overlay.querySelectorAll('button:not(:disabled),input:not(:disabled),select:not(:disabled)')],first=nodes[0],last=nodes.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
setInterval(()=>{if(!state.live||document.hidden||overlay.innerHTML||!document.querySelector('[data-chart-plot]'))return;const data=series(),now=Date.now();data.push(sample(now,scopeId(),state.metric));while(data.length>1&&data[0].t<now-hours()*3600000)data.shift();document.querySelector('[data-chart-plot]').innerHTML=plot(data);document.querySelector('[data-chart-time]').textContent=time(now);document.querySelector('[data-chart-count]').textContent=data.length;document.querySelector('[data-chart-value]').textContent=num(data.at(-1).a)+' '+(state.metric==='storage'?'%':'kW');},5000);
function communityState(c){return !c.sites.length?'normal':c.sites.every(s=>!s.fresh)?'offline':c.sites.some(s=>!s.ready||!s.fresh)?'alerts':'normal';}
function communityList(){const q=(state.communitySearch||'').toLowerCase();let list=communities.map((c,i)=>({...c,index:i,status:communityState(c)})).filter(c=>(c.name+' '+c.place).toLowerCase().includes(q)&&(!state.communityFilter||state.communityFilter==='all'||c.status===state.communityFilter));list.sort((a,b)=>state.communitySort==='status'?a.status.localeCompare(b.status):state.communitySort==='activity'?b.sites.length-a.sites.length:a.name.localeCompare(b.name));return list.length?`<ul class="community-select-list">${list.map(c=>`<li><article class="community-select-item"><div class="community-select-icon">${icon('sun')}</div><div class="community-select-main"><h2>${esc(c.name)}</h2><span>${esc(c.place)}</span><p>${esc(c.description||'Energy community with generation, storage and flexible loads.')}</p><div class="community-select-meta"><small>${icon('building')}${c.sites.length} sites</small><small>${icon('grid')}${c.sites.reduce((n,s)=>n+s.assets.length,0)+(c.vehicles?.length||0)} assets</small></div></div><div class="community-select-side"><button class="btn primary" data-community="${c.index}">View ${icon('arrow')}</button>${status(c.status==='alerts'?'With alerts':c.status==='offline'?'Offline':'Normal',c.status==='alerts'?'warn':c.status==='offline'?'unknown':'')}</div></article></li>`).join('')}</ul>`:'<div class="empty">No communities match your filters.</div>';}
function allCommunities(){return `<div class="community-select-shell"><section class="community-select-panel"><header class="community-select-panel-head"><div><div class="eyebrow">Energy communities</div><h1>Choose a community</h1><p>Enter a REC workspace with the selected community as context.</p></div><label class="search">${icon('search')}<input id="community-search" aria-label="Search communities" placeholder="Search communities…" value="${esc(state.communitySearch||'')}"></label></header><div class="community-select-controls"><label><span>Sort by</span><select id="community-sort"><option value="name" ${state.communitySort==='name'?'selected':''}>Name A–Z</option><option value="status" ${state.communitySort==='status'?'selected':''}>Status</option><option value="activity" ${state.communitySort==='activity'?'selected':''}>Activity</option></select></label><label><span>Status</span><select id="community-filter"><option value="all">All states</option><option value="normal" ${state.communityFilter==='normal'?'selected':''}>Normal</option><option value="alerts" ${state.communityFilter==='alerts'?'selected':''}>With alerts</option><option value="offline" ${state.communityFilter==='offline'?'selected':''}>Offline</option></select></label><button class="btn primary community-select-create" data-action="new-community">${icon('plus')} New Community</button></div><div id="community-results">${communityList()}</div></section></div>`;}
function userMenu(){return state.userOpen?`<section class="user-menu" role="dialog" aria-label="User menu"><header><strong>REC Manager</strong><small>rec@energaize.io</small></header><button class="menu-link" data-action="profile">${icon('user')} Profile</button><button class="btn danger" data-action="logout">${icon('logout')} Logout</button></section>`:'';}
function loginPage(){return `<main class="connection-screen"><a href="/login">Return to sign in</a></main>`;}
function render(){chartCounter++;if(state.loggedIn===false){app.innerHTML=loginPage()+`<footer class="prototypebar">Interactive prototype · demo session only</footer>`;return;}const select=state.page==='communities';app.innerHTML=`<header class="topbar"><div class="topbar-left"><button class="brand" data-action="all-communities" aria-label="All communities"><img class="brand-logo" src="assets/energaize-light.png" alt="EnergAIze"></button>${!select?`<div class="community-context switchwrap"><button class="community-context-main" data-action="switch" aria-expanded="${state.dropdown}" aria-label="Select community"><span class="community-context-copy"><small>Community</small><strong>${esc(comm().name)}</strong></span>${icon('down')}</button>${state.dropdown?`<div class="dropdown" aria-label="Community picker">${communities.map((c,i)=>`<button data-community="${i}"><span><strong>${esc(c.name)}</strong><br><small>${c.sites.length} sites · ${esc(c.place)}</small></span>${state.community===i?icon('check'):''}</button>`).join('')}<div class="dropdown-divider"></div><button data-action="all-communities">${icon('grid')} All communities</button><button data-action="new-community">${icon('plus')} New community</button></div>`:''}</div>`:''}</div><nav class="topbar-nav" aria-label="Primary navigation">${select?'<span class="top-tab is-active">Communities</span>':[['overview','Overview'],['sites','Inventory']].map(([id,l])=>`<button class="top-tab ${state.page===id?'is-active':''}" data-page="${id}" ${state.page===id?'aria-current="page"':''}>${l}</button>`).join('')}</nav><div class="topbar-right">${!select?`<button class="icon-btn ${state.page==='admin'?'is-active':''}" data-page="admin" aria-label="Administration" title="Administration">${icon('settings')}</button><button class="icon-btn" data-action="community-settings" aria-label="Settings" title="Settings">${icon('gear')}</button>`:''}<button class="avatar-btn" data-action="account" aria-expanded="${!!state.userOpen}" aria-label="Open user menu" title="User menu"><span class="avatar-media">RM</span>${icon('settings')}</button>${userMenu()}</div></header><div class="shell ${select?'community-selection':''}"><main class="main ${state.page==='sites'&&state.site?'site-main':''} content">${select?allCommunities():state.page==='overview'?overview():state.page==='sites'?(state.site?siteDetail():siteList()):state.page==='insights'?insights():admin()}</main></div><footer class="prototypebar">Interactive prototype <span>·</span> ${comm().workbook?"Workbook inventory · No live data":"Simulated data"} <span>·</span> Changes reset on reload</footer>`;}
function symbolNode(cx,cy,label,ic,action,primary=false){return `<g class="symbol-node ${primary?'primary-node':''}" role="button" tabindex="0" aria-label="${esc(label)}" data-${action[0]}="${esc(action[1])}" transform="translate(${cx} ${cy})">${ic==='network'?'':`<circle r="30" fill="${primary?'#e5f4eb':'#f0f4f2'}"/>`}<g transform="translate(-17 -17) scale(1.42)" fill="none" stroke="${primary?'#16825a':'#475e53'}" stroke-width="1.35" stroke-linecap="round" stroke-linejoin="round"><path d="${paths[ic]}"/></g><text x="0" y="52" text-anchor="middle" class="symbol-name">${esc(label)}</text></g>`;}
function plainLimit(x,y,lines,anchor='start'){return `<g class="power-label">${lines.map((line,i)=>`<text x="${x}" y="${y+i*21}" text-anchor="${anchor}">${line}</text>`).join('')}</g>`;}
function graphToolbar(titleText){return `<div class="sectionhead"><div><h2>${titleText}</h2><p class="subtitle">Select a node to explore its equipment and measurements.</p></div>${button('Export SVG','export-topology','download')}</div>`;}
function siteTopology(){const s=chosen();return graphToolbar('Energy topology')+`<div class="topology print-topology"><svg xmlns="http://www.w3.org/2000/svg" class="topograph publication-graph" viewBox="0 0 1000 600" role="group" aria-label="Site energy topology"><title>${esc(s.name)} · conceptual energy topology</title>${arrowDefs()}<path class="edge energy-edge" d="M500 112V165" marker-start="url(#arrow-end)" marker-end="url(#arrow-end)"/><path class="edge" d="M500 247V280"/><path class="edge" d="M500 367V410 M150 430V422Q150 410 162 410H838Q850 410 850 422V430"/><path class="edge energy-edge" d="M150 430V487" marker-start="url(#arrow-end)"/><path class="edge energy-edge" d="M500 410V487" marker-start="url(#arrow-end)" marker-end="url(#arrow-end)"/><path class="edge energy-edge" d="M850 430V487" marker-end="url(#arrow-end)"/>${plainLimit(550,133,[`Import ≤ ${num(s.importLimit)} kW`,`Export ≤ ${num(s.exportLimit)} kW`])}${plainLimit(150,448,['Generation 0–5 kW'],'middle')}${plainLimit(555,444,['Charge 0–3 kW','Discharge 0–3 kW'])}${plainLimit(850,448,['Charge 0–7.4 kW'],'middle')}${symbolNode(500,60,'Utility grid','network',['action','grid-info'])}${symbolNode(500,195,'Grid meter','bolt',['asset','meter'])}${symbolNode(500,310,s.name,s.icon,['action','site-overview'],true)}${symbolNode(150,520,'Solar PV','sun',['asset','pv'])}${symbolNode(500,520,'Battery','battery',['asset','battery'])}${symbolNode(850,520,'EV charger','car',['asset','charger'])}</svg></div><p class="footnote">Conceptual layout · example operating limits. Arrows show permitted directions, not measured flows.</p>`;}
function communityTopology(){const list=scoped(),width=Math.max(720,list.length*170),center=width/2,start=(width-Math.max(0,list.length-1)*170)/2;return graphToolbar('Community topology')+`<div class="topology print-topology"><svg xmlns="http://www.w3.org/2000/svg" class="topograph publication-graph community-symbols" viewBox="0 0 ${width} 370" role="group" aria-label="Community topology"><title>${esc(comm().name)} · community membership</title><path class="edge" d="M${center} 122V180 ${list.length>1?`M${start} 192Q${start} 180 ${start+12} 180H${start+(list.length-1)*170-12}Q${start+(list.length-1)*170} 180 ${start+(list.length-1)*170} 192 ${list.map((_,i)=>`M${start+i*170} ${i===0||i===list.length-1?192:180}V242`).join(' ')}`:list.length?`M${center} 180V242`:''}"/>${symbolNode(center,70,comm().name,'tree',['page','overview'],true)}${list.map((s,i)=>symbolNode(start+i*170,272,s.name,s.icon,['site',s.id])).join('')}</svg></div><p class="footnote">Community membership, not a physical electrical network.</p>`;}
function exportTopology(){const original=document.querySelector('.publication-graph');if(!original)return;const svg=original.cloneNode(true);const vb=svg.getAttribute('viewBox').split(' ').map(Number);svg.setAttribute('width',vb[2]);svg.setAttribute('height',vb[3]);svg.removeAttribute('class');const style=document.createElementNS('http://www.w3.org/2000/svg','style');style.textContent='.edge{stroke:#93a99b;stroke-width:1.5;fill:none}.energy-edge{stroke-width:1.7}.symbol-name{font:500 16px Arial,sans-serif;fill:#23392c}.power-label text{font:13px Arial,sans-serif;fill:#657a6d;paint-order:stroke;stroke:white;stroke-width:9px;stroke-linejoin:round}';svg.prepend(style);const bg=document.createElementNS('http://www.w3.org/2000/svg','rect');bg.setAttribute('width','100%');bg.setAttribute('height','100%');bg.setAttribute('fill','white');svg.insertBefore(bg,style);svg.querySelectorAll('[tabindex]').forEach(n=>{n.removeAttribute('tabindex');n.removeAttribute('role');});const blob=new Blob([new XMLSerializer().serializeToString(svg)],{type:'image/svg+xml'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=(state.site?chosen().name:comm().name).replace(/[^a-z0-9_-]/gi,'-')+'-topology.svg';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function openEquipment(id){state.equipment=id;state.deviceTab='overview';state.deviceField='primary';state.metric={meter:'grid',pv:'solar',battery:'storage',charger:'charging'}[id];render();}
function equipmentContent(){const a=currentAssets().find(x=>x.id===state.equipment),s=chosen(),available=s.fresh&&a.value!=null;const alternatives={meter:['Voltage','Cumulative energy'],pv:['Inverter temperature','Voltage'],battery:['Temperature','Charge/discharge power'],charger:['Vehicle state of charge','Session energy']};const selector=`<label class="metric-select">Measurement<select id="equipment-series"><option value="primary" ${state.deviceField==='primary'?'selected':''}>${a.quantity}</option>${alternatives[a.id].map((x,i)=>`<option value="${i}" ${state.deviceField===String(i)?'selected':''}>${x} · not configured</option>`).join('')}</select></label>`;const body=state.deviceTab==='sensors'?`<section class="surface"><div class="sectionhead"><h2>Sensors</h2>${button('Configure sensors','configure-equipment','gear')}</div><div class="tablewrap"><table><thead><tr><th>Measurement</th><th>Latest value</th><th>Tag</th><th>Interval</th><th>State</th></tr></thead><tbody><tr><td>${a.quantity}</td><td>${a.value==null?'—':num(a.value)+' '+a.unit}</td><td>${esc(a.tag||'Not configured')}</td><td>${a.interval} s</td><td>${available?'Available':!s.fresh?'Stale':'Missing'}</td></tr>${alternatives[a.id].map(x=>`<tr><td>${x}</td><td>—</td><td>Not configured</td><td>—</td><td>No observations</td></tr>`).join('')}</tbody></table></div></section>`:`<div class="summaryrow"><div><small>${a.quantity}</small><strong>${a.value==null?'No reading':num(a.value)+' '+a.unit}</strong></div><div><small>Data state</small><strong>${available?'Available':!s.fresh?'Stale · 2 hours':'Missing'}</strong></div><div><small>Expected interval</small><strong>${a.interval} s</strong></div><div><small>Source</small><strong>Example data service</strong></div></div><div class="sectionhead"><h2>${state.deviceTab==='overview'?'Measurements':'Historical & live data'}</h2>${selector}</div>${state.deviceField==='primary'&&available?chart():`<section class="surface empty">${state.deviceField!=='primary'?'This measurement is not configured.':!s.fresh?'There are no recent observations.':'No observations received for this sensor.'}<p class="subtitle">Missing data is not zero. ${a.tag?'Check the source and its latest timestamp.':'Configure the sensor tag to start collecting it.'}</p>${button('Configure sensors','configure-equipment','gear')}</section>`}<div class="device-bottom"><section><h2>Technical details</h2><div class="kv"><div><small>Equipment type</small><strong>${a.kind}</strong></div><div><small>Operating limits</small><strong>${a.limit}</strong></div><div><small>Assigned site</small><strong>${esc(s.name)}</strong></div><div><small>External tag</small><strong class="wrap">${esc(a.tag||'Not configured')}</strong></div></div></section><section><h2>Missing measurements</h2>${alternatives[a.id].map(x=>`<div class="record">${icon('alert')}<div><strong>${x}</strong><small>Not configured · no data available</small></div></div>`).join('')}</section></div>`;return `<div class="workspace">${tree()}<div class="detail"><div class="equipment-breadcrumb"><button data-action="site-overview">${esc(s.name)}</button>${icon('right')}<span>${a.name}</span></div><div class="sitehead"><div class="equipment-heading"><span class="device-symbol">${icon(a.icon)}</span><div><h1>${a.name}</h1><p class="subtitle">${a.kind} · ${esc(s.name)}</p></div></div>${button('Settings','configure-equipment','gear')}</div><nav class="tabs" aria-label="Equipment sections">${[['overview','Overview'],['measurements','Measurements'],['sensors','Sensors']].map(([v,l])=>`<button data-device-tab="${v}" class="${state.deviceTab===v?'active':''}">${l}</button>`).join('')}</nav>${body}</div></div>`;}
function siteDetail(){return state.equipment?equipmentContent():siteDetailOriginal();}
function insights(){return title('Insights','Community measurements, trends and performance.')+`<nav class="tabs" aria-label="Insight sections"><button data-insight-tab="measurements" class="${state.insightTab!=='kpis'?'active':''}">Measurements</button><button data-insight-tab="kpis" class="${state.insightTab==='kpis'?'active':''}">KPIs</button></nav>`+(state.insightTab==='kpis'?insightsOriginal().slice(insightsOriginal().indexOf('<div class="notice')):dataExplorer());}

document.addEventListener('input',e=>{if(e.target.id==='community-search'){state.communitySearch=e.target.value;document.getElementById('community-results').innerHTML=communityList();}});
document.addEventListener('change',e=>{if(e.target.id==='community-sort'){state.communitySort=e.target.value;document.getElementById('community-results').innerHTML=communityList();}if(e.target.id==='community-filter'){state.communityFilter=e.target.value;document.getElementById('community-results').innerHTML=communityList();}if(e.target.id==='equipment-series'){state.deviceField=e.target.value;render();}});
render();
